        stack.append(i)
    elif c==')':
        j=stack.pop()
        pairs[j]=i; pairs[i]=j

def fold(s):
    fc=RNA.fold_compound(s)
    mfe=fc.mfe()
    return mfe

def bpset(s):
    f=fold(s)
    st=[]; ps=set()
    for i,c in enumerate(f):
        if c=='(': st.append(i)
        elif c==')':
            j=st.pop(); ps.add((min(i,j),max(i,j)))
    return ps,f

