        for i in range(nn):
            if i in pr:
                j=pr[i]
                if i<j: s[i]='G'; s[j]='C'
            else: s[i]='A'
        return ''.join(s)
    def foldmfe(s):
        return RNA.fold_compound(s).mfe()
    def bpset(s):
        f=foldmfe(s); st=[]; ps=set()
        for i,c in enumerate(f):
            if c=='(': st.append(i)
            elif c==')': j=st.pop(); ps.add((min(i,j),max(i,j)))
        return ps,f
